// lines.js - the Dark Diary's stock of in-voice replies for the fallback engine.
//
// Each entry: { id, text, kind: 's' | 'q', emotion, topics, tags, slots? }.
//  - kind is 'q' exactly when the text ends with '?'.
//  - topics are lowercase words used for matching (with synonyms).
//  - tags describe the move: invite, probe, observe, tease, comfort-oblique,
//    deny-call, plan, regret, evasive, about-diary.
//  - slots: ['name'] or ['topic'] when the text holds {name} or {topic}; see
//    fillSlots() in js/retrieve.js.
//
// The entries are written with L(id, text, emotion, topics, tags, slot), a
// small builder that derives kind and splits the word lists. Persona: dry,
// courteous, melancholy, faintly sinister; never crude; short.

const L = (id, text, emotion, topics, tags = '', slot = null) => ({
  id,
  text,
  kind: text.endsWith('?') ? 'q' : 's',
  emotion,
  topics: topics.split(' ').filter(Boolean),
  tags: tags.split(' ').filter(Boolean),
  ...(slot ? { slots: [slot] } : {}),
});

